args.CommandLine:
$files = @(
    "specs\001-pitwall-ai\plan.md",
    "specs\001-pitwall-ai\research.md",
    "specs\001-pitwall-ai\data-model.md",
    "specs\001-pitwall-ai\contracts\api-contracts.md",
    "specs\001-pitwall-ai\quickstart.md"
)
foreach ($f in $files) {
    $full = Join-Path "D:\Learning\F1_Tracker\f1-race-engineer" $f
    $matches = Select-String -Path $full -Pattern "\[[A-Z_]{3,}\]|\[###|TODO|FIXME"
    if ($matches) {
        Write-Output "Placeholders in $f :"
        $matches | ForEach-Object { $_.Line }
    } else {
        Write-Output "No placeholders in $f"
    }
}

python -c "
import re
from pathlib import Path

content = Path('specs/001-pitwall-ai/tasks.md').read_text(encoding='utf-8')
tasks = re.findall(r'^- \[ \] (T\d+)\s+(\[P\]\s+)?(\[US\d+\]\s+)?(.+)$', content, re.M)
print(f'Total tasks parsed: {len(tasks)}')

stories = {}
for t in tasks:
    tid, p, story, desc = t
    story_key = story.strip() if story else 'Setup/Foundational/Polish'
    stories[story_key] = stories.get(story_key, 0) + 1

for s, count in sorted(stories.items()):
    print(f'  {s}: {count}')

# Check for invalid lines starting with '- [ ]' that didn't match the regex
all_checkboxes = re.findall(r'^- \[ \].*$', content, re.M)
if len(all_checkboxes) != len(tasks):
    print(f'WARNING: {len(all_checkboxes)} checkbox lines found, but only {len(tasks)} matched task pattern!')
    for line in all_checkboxes:
        if not re.match(r'^- \[ \] T\d+\s+', line):
            print('  Invalid line:', line)
else:
    print('ALL tasks strictly follow the checklist format!')
"

python -c "
import re
from pathlib import Path

dm_text = Path('specs/001-pitwall-ai/data-model.md').read_text(encoding='utf-8')
tasks_text = Path('specs/001-pitwall-ai/tasks.md').read_text(encoding='utf-8')

citations = re.findall(r'\(cites `?data-model\.md`?: ([^\)]+)\)', tasks_text)
cited_tokens = []
for c in citations:
    for token in c.split(','):
        t = token.strip().strip('`')
        if t:
            cited_tokens.append(t)

print(f'Total cited tokens in tasks: {len(cited_tokens)}')

tables = re.findall(r'#### (\w+)\s*\n\n\| Column \| Type \| Nullable \| Description \|\n\|[-|\s]+\|\n((?:\| [^|\n]+ \| [^|\n]+ \| [^|\n]+ \| [^|\n]+ \|\n)+)', dm_text)

constrained_fields = []
for table_name, table_body in tables:
    for line in table_body.strip().splitlines():
        parts = [p.strip() for p in line.split('|')[1:-1]]
        col, ctype, nullable, desc = parts
        if nullable == 'NO' or 'PK' in desc or 'FK' in desc or '1950' in desc or 'VARCHAR(3)' in ctype:
            constrained_fields.append(f'{table_name}.{col}')

unref = []
for f in constrained_fields:
    cited = any(f in t for t in cited_tokens)
    if not cited:
        unref.append(f)

print(f'Constrained fields: {len(constrained_fields)}, Cited: {len(constrained_fields)-len(unref)}, Unreferenced: {len(unref)}')
if unref:
    print('Unreferenced constrained fields:', unref)
"

