"""
Conversation session management for PitWall AI.
Maintains in-memory conversation state with rolling summary and verbatim turns.
Supports context pruning (last 2 turns for local Ollama, last 4-6 turns for Gemini).
"""

from datetime import datetime, timezone
from typing import Dict, List, Optional
import uuid
from pydantic import BaseModel, Field


class TurnMessage(BaseModel):
    role: str  # "user" or "assistant"
    content: str
    timestamp: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))


class ConversationSession:
    def __init__(self, session_id: str, user_id: str):
        self.session_id = session_id
        self.user_id = user_id
        self.rolling_summary: str = ""
        self.turns: List[TurnMessage] = []
        self.created_at: datetime = datetime.now(timezone.utc)
        self.updated_at: datetime = datetime.now(timezone.utc)

    def add_user_message(self, content: str) -> None:
        self.turns.append(TurnMessage(role="user", content=content))
        self.updated_at = datetime.now(timezone.utc)
        self._prune_and_summarize()

    def add_assistant_message(self, content: str) -> None:
        self.turns.append(TurnMessage(role="assistant", content=content))
        self.updated_at = datetime.now(timezone.utc)
        self._prune_and_summarize()

    def _prune_and_summarize(self) -> None:
        """
        Keeps last 6 messages verbatim. Older messages are summarized
        into the rolling summary.
        """
        MAX_VERBATIM = 6
        if len(self.turns) > MAX_VERBATIM:
            overflow_turns = self.turns[:-MAX_VERBATIM]
            summary_parts = []
            for t in overflow_turns:
                prefix = "User" if t.role == "user" else "Engineer"
                summary_parts.append(f"{prefix}: {t.content[:120]}...")

            overflow_summary = " | ".join(summary_parts)
            if self.rolling_summary:
                self.rolling_summary += " | " + overflow_summary
            else:
                self.rolling_summary = overflow_summary

            # Keep only the last MAX_VERBATIM turns
            self.turns = self.turns[-MAX_VERBATIM:]

    def get_context(self, provider: str = "gemini") -> Dict[str, Any]:
        """
        Returns contextual history formatted for LLM invocation.
        For Ollama: Prunes context to the last 2 turns to respect 8GB RAM budget.
        For Gemini: Provides rolling summary + last 4-6 verbatim turns.
        """
        if provider.lower() == "ollama":
            # Last 2 messages only
            selected_turns = self.turns[-2:]
            return {
                "rolling_summary": "",
                "messages": [{"role": t.role, "content": t.content} for t in selected_turns],
            }
        else:
            return {
                "rolling_summary": self.rolling_summary,
                "messages": [{"role": t.role, "content": t.content} for t in self.turns],
            }


class SessionManager:
    """In-memory thread-safe session storage."""

    def __init__(self):
        self._sessions: Dict[str, ConversationSession] = {}

    def get_or_create(self, session_id: Optional[str] = None, user_id: str = "anonymous") -> ConversationSession:
        if session_id and session_id in self._sessions:
            return self._sessions[session_id]

        new_id = session_id or f"ses_{uuid.uuid4().hex[:12]}"
        session = ConversationSession(session_id=new_id, user_id=user_id)
        self._sessions[new_id] = session
        return session

    def get(self, session_id: str) -> Optional[ConversationSession]:
        return self._sessions.get(session_id)

    def delete(self, session_id: str) -> bool:
        if session_id in self._sessions:
            del self._sessions[session_id]
            return True
        return False


# Singleton session manager
session_manager = SessionManager()

"""
Server-Sent Events (SSE) formatting helpers for PitWall AI.
Formats typed events strictly compliant with contracts/api-contracts.md.
"""

import json
from typing import Any, Dict, Optional


def sse_message(event_type: str, data: Dict[str, Any]) -> str:
    """Formats a Server-Sent Event frame."""
    json_data = json.dumps(data, ensure_ascii=False)
    return f"event: {event_type}\ndata: {json_data}\n\n"


def format_session_event(session_id: str) -> str:
    """Emitted immediately upon SSE connection establishment."""
    return sse_message("session", {"session_id": session_id})


def format_status_event(step: str, detail: str) -> str:
    """Emitted during agent reasoning and tool execution stages."""
    return sse_message("status", {"step": step, "detail": detail})


def format_text_event(delta: str) -> str:
    """Emitted as the LLM streams its natural-language commentary."""
    return sse_message("text", {"delta": delta})


def format_chart_event(chart_type: str, spec: Dict[str, Any], caption: str = "") -> str:
    """Emitted once a Plotly JSON specification is generated."""
    return sse_message(
        "chart",
        {
            "chart_type": chart_type,
            "spec": spec,
            "caption": caption,
        },
    )


def format_trace_event(
    data_domain: str,
    query: Optional[str] = None,
    execution_time_ms: Optional[float] = None,
    row_count: Optional[int] = None,
    telemetry_params: Optional[Dict[str, Any]] = None,
    interpolated_points: Optional[int] = None,
    confidence: float = 1.0,
    notes: Optional[str] = None,
) -> str:
    """Emitted with full provenance data for the collapsible Engineering Trace drawer."""
    payload: Dict[str, Any] = {
        "data_domain": data_domain,
        "confidence": confidence,
    }
    if query is not None:
        payload["query"] = query
    if execution_time_ms is not None:
        payload["execution_time_ms"] = execution_time_ms
    if row_count is not None:
        payload["row_count"] = row_count
    if telemetry_params is not None:
        payload["telemetry_params"] = telemetry_params
    if interpolated_points is not None:
        payload["interpolated_points"] = interpolated_points
    if notes is not None:
        payload["notes"] = notes

    return sse_message("trace", payload)


def format_error_event(code: str, message: str, retryable: bool = False) -> str:
    """Emitted if query execution or telemetry processing encounters an error."""
    return sse_message(
        "error",
        {
            "code": code,
            "message": message,
            "retryable": retryable,
        },
    )


def format_done_event(total_duration_ms: int) -> str:
    """Emitted as the final event of the streaming response."""
    return sse_message("done", {"total_duration_ms": total_duration_ms})

