"""
Historical Chart Builders for PitWall AI.
Constructs Plotly JSON specifications for Bar charts, Line charts,
and classification tables adhering to the #0B0F17 dark HUD standard.
"""

from typing import Any, Dict, List, Optional
from backend.app.charts.plotly_theme import get_hud_layout_template, HUD_ACCENT_RED


def build_bar_chart(
    title: str,
    x: List[Any],
    y: List[Any],
    x_title: str = "",
    y_title: str = "",
    marker_color: str = HUD_ACCENT_RED,
) -> Dict[str, Any]:
    """Builds a single-series vertical or horizontal bar chart."""
    layout = get_hud_layout_template()
    layout.update({
        "title": {
            "text": title,
            "font": {"color": "#FFFFFF", "size": 15, "family": "Inter, sans-serif"},
            "x": 0.02,
        },
        "xaxis": {**layout["xaxis"], "title": {"text": x_title, "font": {"color": "#94A3B8"}}},
        "yaxis": {**layout["yaxis"], "title": {"text": y_title, "font": {"color": "#94A3B8"}}},
    })

    trace = {
        "type": "bar",
        "x": x,
        "y": y,
        "marker": {
            "color": marker_color,
            "line": {"color": "#1E293B", "width": 1},
        },
        "text": [str(val) for val in y],
        "textposition": "auto",
        "textfont": {"color": "#FFFFFF", "family": "JetBrains Mono, monospace"},
        "hoverinfo": "x+y",
    }

    return {
        "chart_type": "bar",
        "spec": {
            "data": [trace],
            "layout": layout,
            "config": {"responsive": True, "displayModeBar": False},
        },
        "caption": title,
    }


def build_line_chart(
    title: str,
    x: List[Any],
    y: List[Any],
    x_title: str = "",
    y_title: str = "",
    line_color: str = "#38BDF8",
    name: str = "Series",
) -> Dict[str, Any]:
    """Builds a continuous trend line chart with markers."""
    layout = get_hud_layout_template()
    layout.update({
        "title": {
            "text": title,
            "font": {"color": "#FFFFFF", "size": 15, "family": "Inter, sans-serif"},
            "x": 0.02,
        },
        "xaxis": {**layout["xaxis"], "title": {"text": x_title, "font": {"color": "#94A3B8"}}},
        "yaxis": {**layout["yaxis"], "title": {"text": y_title, "font": {"color": "#94A3B8"}}},
    })

    trace = {
        "type": "scatter",
        "mode": "lines+markers",
        "x": x,
        "y": y,
        "name": name,
        "line": {"color": line_color, "width": 2.5, "shape": "spline"},
        "marker": {"color": line_color, "size": 6},
        "hoverinfo": "x+y",
    }

    return {
        "chart_type": "line",
        "spec": {
            "data": [trace],
            "layout": layout,
            "config": {"responsive": True, "displayModeBar": False},
        },
        "caption": title,
    }


def build_classification_table(
    title: str,
    headers: List[str],
    rows: List[List[Any]],
) -> Dict[str, Any]:
    """Builds a dark HUD Plotly table visualization."""
    layout = get_hud_layout_template()
    layout.update({
        "title": {
            "text": title,
            "font": {"color": "#FFFFFF", "size": 15, "family": "Inter, sans-serif"},
            "x": 0.02,
        },
        "margin": {"l": 20, "r": 20, "t": 50, "b": 20},
    })

    # Transpose rows into column arrays for Plotly Table
    num_cols = len(headers)
    column_values = [[] for _ in range(num_cols)]
    for row in rows:
        for idx in range(num_cols):
            val = row[idx] if idx < len(row) else ""
            column_values[idx].append(str(val) if val is not None else "-")

    trace = {
        "type": "table",
        "header": {
            "values": [f"<b>{h.upper()}</b>" for h in headers],
            "fill": {"color": "#1E293B"},
            "align": "left",
            "font": {"family": "JetBrains Mono, monospace", "size": 12, "color": "#FFFFFF"},
            "height": 30,
        },
        "cells": {
            "values": column_values,
            "fill": {"color": ["#0B0F17", "#121824"]},
            "align": "left",
            "font": {"family": "Inter, sans-serif", "size": 12, "color": "#E2E8F0"},
            "height": 26,
        },
    }

    return {
        "chart_type": "table",
        "spec": {
            "data": [trace],
            "layout": layout,
            "config": {"responsive": True, "displayModeBar": False},
        },
        "caption": title,
    }


def auto_build_historical_chart(
    sql: str,
    columns: List[str],
    data: List[Dict[str, Any]],
    title_hint: Optional[str] = None,
) -> Optional[Dict[str, Any]]:
    """
    Intelligently determines and constructs the most informative Plotly visualization
    for historical query results based on returned columns.
    """
    if not data or not columns:
        return None

    title = title_hint or "Formula 1 Historical Query Results"
    lower_cols = [c.lower() for c in columns]

    # Pattern 1: Classification table (Position + Driver + Constructor)
    if "position" in lower_cols and any(d in lower_cols for d in ["driver_code", "surname", "driver"]):
        display_cols = [c for c in columns if c.lower() in [
            "position", "driver_code", "surname", "constructor", "grid", "points", "status", "finish_time"
        ]]
        if not display_cols:
            display_cols = columns[:6]

        headers = [c.replace("_", " ").title() for c in display_cols]
        rows = [[row.get(c) for c in display_cols] for row in data[:20]]
        return build_classification_table(title, headers, rows)

    # Pattern 2: Trend over Years (Year + numeric metric like points, wins, podiums)
    numeric_cols = [c for c in columns if any(isinstance(row.get(c), (int, float)) for row in data[:5])]
    year_col = next((c for c in columns if "year" in c.lower()), None)

    if year_col and numeric_cols:
        val_col = next((c for c in numeric_cols if c != year_col), None)
        if val_col:
            x_vals = [row.get(year_col) for row in data]
            y_vals = [row.get(val_col) for row in data]
            return build_line_chart(
                title=title,
                x=x_vals,
                y=y_vals,
                x_title="Season Year",
                y_title=val_col.replace("_", " ").title(),
                name=val_col.title(),
            )

    # Pattern 3: Driver / Constructor comparison (Driver/Constructor + numeric)
    label_col = next((c for c in columns if any(k in c.lower() for k in ["driver", "surname", "constructor", "circuit"])), None)
    if label_col and numeric_cols:
        val_col = next((c for c in numeric_cols if c != label_col), None)
        if val_col:
            top_data = data[:15]
            x_vals = [str(row.get(label_col)) for row in top_data]
            y_vals = [row.get(val_col) for row in top_data]
            return build_bar_chart(
                title=title,
                x=x_vals,
                y=y_vals,
                x_title=label_col.replace("_", " ").title(),
                y_title=val_col.replace("_", " ").title(),
            )

    # Fallback to Table for any result with <= 8 columns
    if len(columns) <= 8:
        headers = [c.replace("_", " ").title() for c in columns]
        rows = [[row.get(c) for c in columns] for row in data[:20]]
        return build_classification_table(title, headers, rows)

    return None

import { useState, useEffect } from 'react';
import { User, AuthState } from '../types';

export function useAuth() {
  const [authState, setAuthState] = useState<AuthState>(() => {
    const token = localStorage.getItem('pitwall_token');
    const userStr = localStorage.getItem('pitwall_user');
    if (token && userStr) {
      try {
        return {
          token,
          user: JSON.parse(userStr) as User,
          isAuthenticated: true,
        };
      } catch {
        // invalid JSON
      }
    }
    return { token: null, user: null, isAuthenticated: false };
  });

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const login = async (email: string, password: string): Promise<boolean> => {
    setIsLoading(true);
    setError(null);
    try {
      const res = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.detail || 'Failed to authenticate');
      }

      const data = await res.json();
      localStorage.setItem('pitwall_token', data.access_token);
      localStorage.setItem('pitwall_user', JSON.stringify(data.user));

      setAuthState({
        token: data.access_token,
        user: data.user,
        isAuthenticated: true,
      });
      return true;
    } catch (err: any) {
      setError(err.message || 'Login failed');
      return false;
    } finally {
      setIsLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem('pitwall_token');
    localStorage.removeItem('pitwall_user');
    setAuthState({ token: null, user: null, isAuthenticated: false });
  };

  return {
    ...authState,
    isLoading,
    error,
    login,
    logout,
  };
}

