export interface User {
  id: string;
  email: string;
  display_name: string;
}

export interface AuthState {
  user: User | null;
  token: string | null;
  isAuthenticated: boolean;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;
  isStreaming?: boolean;
}

export interface EngineeringTrace {
  data_domain: 'historical' | 'telemetry' | 'mixed';
  query?: string;
  execution_time_ms?: number;
  row_count?: number;
  telemetry_params?: {
    year?: number;
    grand_prix?: string;
    session_type?: string;
    drivers?: string[];
    turn_number?: number;
    corner_nickname?: string;
  };
  interpolated_points?: number;
  confidence: number;
  notes?: string;
}

export interface PlotlySpec {
  data: any[];
  layout: Record<string, any>;
  config?: Record<string, any>;
}

export interface SSEStatusEvent {
  step: string;
  detail: string;
}

import { useState, useCallback } from 'react';
import { ChatMessage, EngineeringTrace, PlotlySpec } from '../types';

interface UseSSEStreamReturn {
  messages: ChatMessage[];
  currentStatus: string | null;
  currentTrace: EngineeringTrace | null;
  currentChart: PlotlySpec | null;
  isStreaming: boolean;
  sessionId: string | null;
  sendMessage: (text: string) => Promise<void>;
  resetChat: () => void;
}

export function useSSEStream(token?: string | null): UseSSEStreamReturn {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [currentStatus, setCurrentStatus] = useState<string | null>(null);
  const [currentTrace, setCurrentTrace] = useState<EngineeringTrace | null>(null);
  const [currentChart, setCurrentChart] = useState<PlotlySpec | null>(null);
  const [isStreaming, setIsStreaming] = useState(false);
  const [sessionId, setSessionId] = useState<string | null>(null);

  const sendMessage = useCallback(
    async (text: string) => {
      if (!text.trim() || isStreaming) return;

      const userMsg: ChatMessage = {
        id: `usr_${Date.now()}`,
        role: 'user',
        content: text.trim(),
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      };

      setMessages((prev) => [...prev, userMsg]);
      setIsStreaming(true);
      setCurrentStatus('Initializing connection to Pit Wall...');

      const assistantMsgId = `ast_${Date.now()}`;
      let accumulatedText = '';

      try {
        const headers: Record<string, string> = {
          'Content-Type': 'application/json',
        };
        if (token) {
          headers['Authorization'] = `Bearer ${token}`;
        }

        const res = await fetch('/api/chat/stream', {
          method: 'POST',
          headers,
          body: JSON.stringify({
            message: text.trim(),
            session_id: sessionId,
          }),
        });

        if (!res.ok) {
          throw new Error(`HTTP ${res.status}: Failed to initiate stream`);
        }

        const reader = res.body?.getReader();
        if (!reader) throw new Error('ReadableStream not available');

        const decoder = new TextDecoder('utf-8');
        let buffer = '';

        while (true) {
          const { value, done } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const frames = buffer.split('\n\n');
          buffer = frames.pop() || '';

          for (const frame of frames) {
            if (!frame.trim()) continue;

            const lines = frame.split('\n');
            let eventType = 'message';
            let dataStr = '';

            for (const line of lines) {
              if (line.startsWith('event: ')) {
                eventType = line.slice(7).trim();
              } else if (line.startsWith('data: ')) {
                dataStr = line.slice(6).trim();
              }
            }

            if (!dataStr) continue;

            try {
              const data = JSON.parse(dataStr);

              switch (eventType) {
                case 'session':
                  if (data.session_id) setSessionId(data.session_id);
                  break;

                case 'status':
                  setCurrentStatus(data.detail || data.step);
                  break;

                case 'text':
                  if (data.delta) {
                    accumulatedText += data.delta;
                    setMessages((prev) => {
                      const existing = prev.find((m) => m.id === assistantMsgId);
                      if (existing) {
                        return prev.map((m) =>
                          m.id === assistantMsgId
                            ? { ...m, content: accumulatedText, isStreaming: true }
                            : m
                        );
                      } else {
                        return [
                          ...prev,
                          {
                            id: assistantMsgId,
                            role: 'assistant',
                            content: accumulatedText,
                            timestamp: new Date().toLocaleTimeString([], {
                              hour: '2-digit',
                              minute: '2-digit',
                            }),
                            isStreaming: true,
                          },
                        ];
                      }
                    });
                  }
                  break;

                case 'chart':
                  if (data.spec) {
                    setCurrentChart(data.spec);
                  }
                  break;

                case 'trace':
                  setCurrentTrace(data);
                  break;

                case 'error':
                  setCurrentStatus(`Error: ${data.message}`);
                  break;

                case 'done':
                  setCurrentStatus(null);
                  setMessages((prev) =>
                    prev.map((m) =>
                      m.id === assistantMsgId ? { ...m, isStreaming: false } : m
                    )
                  );
                  break;
              }
            } catch (jsonErr) {
              console.warn('Failed to parse SSE JSON chunk:', dataStr, jsonErr);
            }
          }
        }
      } catch (err: any) {
        console.error('SSE streaming error:', err);
        setMessages((prev) => [
          ...prev,
          {
            id: `err_${Date.now()}`,
            role: 'assistant',
            content: `Telemetry error: ${err.message || 'Connection lost to PitWall server.'}`,
            timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            isStreaming: false,
          },
        ]);
      } finally {
        setMessages((prev) =>
          prev.map((m) =>
            m.id === assistantMsgId ? { ...m, isStreaming: false } : m
          )
        );
        setIsStreaming(false);
        setCurrentStatus(null);
      }
    },
    [isStreaming, sessionId, token]
  );

  const resetChat = useCallback(() => {
    setMessages([]);
    setCurrentStatus(null);
    setCurrentTrace(null);
    setCurrentChart(null);
    setSessionId(null);
  }, []);

  return {
    messages,
    currentStatus,
    currentTrace,
    currentChart,
    isStreaming,
    sessionId,
    sendMessage,
    resetChat,
  };
}

import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Terminal, User as UserIcon } from 'lucide-react';
import { ChatMessage } from '../../types';

interface MessageBubbleProps {
  message: ChatMessage;
}

export function MessageBubble({ message }: MessageBubbleProps) {
  const isAssistant = message.role === 'assistant';

  return (
    <div
      className={`flex flex-col space-y-1.5 ${
        isAssistant ? 'items-start' : 'items-end'
      }`}
    >
      {/* Header bar: role icon, label, and timestamp */}
      <div className="flex items-center space-x-1.5 text-[11px] font-mono text-[#94A3B8]">
        {isAssistant ? (
          <>
            <Terminal className="h-3 w-3 text-[#E10600]" />
            <span className="font-semibold text-[#E10600]">PITWALL ENGINEER</span>
          </>
        ) : (
          <>
            <UserIcon className="h-3 w-3 text-[#38BDF8]" />
            <span className="font-semibold text-[#38BDF8]">YOU</span>
          </>
        )}
        <span>•</span>
        <span>{message.timestamp}</span>
      </div>

      {/* Message content bubble */}
      <div
        className={`max-w-[92%] rounded-lg px-4 py-3 text-sm leading-relaxed ${
          isAssistant
            ? 'border border-[#1E293B] bg-[#121824] text-[#E2E8F0] shadow-sm'
            : 'border border-[#38BDF8]/20 bg-[#1E293B] text-white'
        }`}
      >
        {isAssistant ? (
          <div className="markdown-container">
            <ReactMarkdown
              remarkPlugins={[remarkGfm]}
              components={{
                p: ({ children }) => (
                  <p className="mb-2 last:mb-0 leading-relaxed font-sans">{children}</p>
                ),
                strong: ({ children }) => (
                  <strong className="font-bold text-[#F8FAFC]">{children}</strong>
                ),
                em: ({ children }) => (
                  <em className="italic text-[#E2E8F0]">{children}</em>
                ),
                ul: ({ children }) => (
                  <ul className="my-1.5 ml-4 list-disc space-y-0.5 text-xs text-[#E2E8F0]">
                    {children}
                  </ul>
                ),
                ol: ({ children }) => (
                  <ol className="my-1.5 ml-4 list-decimal space-y-0.5 text-xs text-[#E2E8F0]">
                    {children}
                  </ol>
                ),
                li: ({ children }) => (
                  <li className="leading-relaxed">{children}</li>
                ),
                code: ({ className, children, ...props }: any) => {
                  const isMultiLine = String(children).includes('\n');
                  if (!isMultiLine && !className) {
                    return (
                      <code
                        className="rounded border border-[#1E293B] bg-[#0B0F17] px-1.5 py-0.5 font-mono text-[11px] text-[#38BDF8]"
                        {...props}
                      >
                        {children}
                      </code>
                    );
                  }
                  return (
                    <pre className="my-2 overflow-x-auto rounded border border-[#1E293B] bg-[#0B0F17] p-2.5 font-mono text-xs text-[#38BDF8]">
                      <code {...props}>{children}</code>
                    </pre>
                  );
                },
                table: ({ children }) => (
                  <div className="my-2 overflow-x-auto rounded border border-[#1E293B]">
                    <table className="min-w-full divide-y divide-[#1E293B] text-xs font-mono">
                      {children}
                    </table>
                  </div>
                ),
                thead: ({ children }) => (
                  <thead className="bg-[#1E293B]/60 text-[#94A3B8]">
                    {children}
                  </thead>
                ),
                th: ({ children }) => (
                  <th className="px-3 py-1.5 text-left font-semibold text-[#94A3B8]">
                    {children}
                  </th>
                ),
                tbody: ({ children }) => (
                  <tbody className="divide-y divide-[#1E293B]/40 bg-[#0B0F17]/40">
                    {children}
                  </tbody>
                ),
                td: ({ children }) => (
                  <td className="px-3 py-1.5 text-[#E2E8F0]">
                    {children}
                  </td>
                ),
                h1: ({ children }) => (
                  <h1 className="text-base font-bold text-white mb-2">{children}</h1>
                ),
                h2: ({ children }) => (
                  <h2 className="text-sm font-bold text-white mb-1.5">{children}</h2>
                ),
                h3: ({ children }) => (
                  <h3 className="text-xs font-bold text-white mb-1">{children}</h3>
                ),
                blockquote: ({ children }) => (
                  <blockquote className="border-l-2 border-[#E10600] pl-3 italic text-[#94A3B8] my-1.5 text-xs">
                    {children}
                  </blockquote>
                ),
              }}
            >
              {message.content}
            </ReactMarkdown>
            {message.isStreaming && (
              <span
                className="inline-block w-1.5 h-3.5 ml-1 bg-[#E10600] animate-pulse align-middle"
                title="Race engineer streaming..."
              />
            )}
          </div>
        ) : (
          <p className="whitespace-pre-wrap font-sans">{message.content}</p>
        )}
      </div>
    </div>
  );
}

