              <span>{drvB}: {s3.driver_b.toFixed(3)}s</span>
            </div>
          </div>
        )}

        {/* Speed Trap */}
        {speedTrap && (
          <div className="rounded border border-[#1E293B] bg-[#0B0F17] p-2">
            <div className="flex items-center justify-between text-[10px] text-[#94A3B8] mb-1">
