import { Flag, CloudSun, Compass, Database } from 'lucide-react';
import { PlotlySpec, StandardizedDriverMeta } from '../../types';

interface MetadataBarProps {
  chart: PlotlySpec | null;
  minimap?: PlotlySpec | null;
}

export function MetadataBar({ chart, minimap }: MetadataBarProps) {
  if (!chart || (!chart.data && !chart.layout)) return null;

  const meta = chart.metadata || {};
  const isHistorical = meta.domain === 'historical';

  // 1. Event & Session
  const year = meta.year;
  const gpName = meta.grand_prix || meta.event_name;
  const sessionName = meta.session_name || meta.session_type;

  // 2. Mode / Concept Label
  let modeLabel = meta.mode_label;
  if (!modeLabel) {
    if (chart.chart_type === 'tyre_degradation') {
      modeLabel = 'Tyre Stint Degradation & Strategy';
    } else if (chart.chart_type === 'full_lap_comparison') {
      modeLabel = 'Full-Lap Overlay • All Sectors';
    } else if (chart.chart_type === 'corner_comparison' || Boolean(minimap)) {
      const corner = meta.corner_nickname || (meta.turn_number ? `Turn ${meta.turn_number}` : 'Corner Comparison');
      modeLabel = corner;
    } else if (isHistorical) {
      modeLabel = 'Historical Analytics • DuckDB';
    }
  }

  // 3. Normalize Drivers: support both StandardizedDriverMeta and legacy string array
  const rawDrivers = meta.drivers || [];
  const normalizedDrivers: StandardizedDriverMeta[] = rawDrivers.map((d, idx) => {
    if (typeof d === 'string') {
      const fallbackCompounds = meta.compounds || [];
      return {
        code: d,
        color: idx === 0 ? '#3671C6' : '#FF8000',
        compound: fallbackCompounds[idx],
      };
    }
    return d;
  });

  const hasDrivers = normalizedDrivers.length > 0;
  const trackStatus = meta.track_status;

  return (
    <div className="flex flex-wrap items-center justify-between gap-2 rounded-md border border-[#1E293B] bg-[#121824]/90 px-3.5 py-2 font-mono text-xs shadow-sm">
      {/* Event and Session */}
      <div className="flex items-center space-x-2">
        <Flag className="h-3.5 w-3.5 text-[#E10600]" />
        {(year || gpName) && (
          <span className="font-bold tracking-wider text-white">
            {[year, gpName ? gpName.toUpperCase() : null].filter(Boolean).join(' ')}
          </span>
        )}
        {sessionName && (
          <span className="rounded bg-[#1E293B] px-1.5 py-0.5 text-[10px] text-[#38BDF8]">
            {sessionName}
          </span>
        )}
      </div>

      {/* Mode / Corner / Scope Reference */}
      {modeLabel && (
        <div className="flex items-center space-x-1.5 text-[#94A3B8]">
          {isHistorical ? (
            <Database className="h-3.5 w-3.5 text-[#38BDF8]" />
          ) : (
            <Compass className="h-3.5 w-3.5 text-[#38BDF8]" />
          )}
          <span className="font-semibold text-[#F8FAFC]">{modeLabel}</span>
        </div>
      )}

      {/* Driver Badges or Historical Scope Badge */}
      {hasDrivers ? (
        <div className="flex items-center space-x-2">
          {normalizedDrivers.map((drv, idx) => (
            <div key={`${drv.code}-${idx}`} className="flex items-center space-x-2">
              {idx > 0 && <span className="text-[#64748B] font-bold">vs</span>}
              <div
                className="flex items-center space-x-1 rounded bg-[#0B0F17] px-2 py-0.5 border"
                style={{ borderColor: drv.color ? `${drv.color}60` : '#38BDF860' }}
              >
                <span
                  className="h-2 w-2 rounded-full"
                  style={{ backgroundColor: drv.color || '#38BDF8' }}
                />
                <span className="font-bold text-white">{drv.code}</span>
                {drv.compound && (
                  <span className="rounded bg-white/10 px-1 text-[9px] font-bold text-white">
                    {drv.compound}
                  </span>
                )}
              </div>
            </div>
          ))}
        </div>
      ) : isHistorical ? (
        <div className="flex items-center space-x-1 rounded bg-[#0B0F17] px-2.5 py-0.5 border border-[#38BDF8]/30 text-[10px] text-[#38BDF8]">
          <span className="h-1.5 w-1.5 rounded-full bg-[#38BDF8]"></span>
          <span className="font-semibold tracking-wider">HISTORICAL SQL • DUCKDB</span>
        </div>
      ) : null}

      {/* Optional Track Conditions */}
      {trackStatus && (
        <div className="flex items-center space-x-1 text-[#94A3B8]">
          <CloudSun className="h-3.5 w-3.5 text-amber-400" />
          <span className="text-[11px]">Track: {trackStatus}</span>
        </div>
      )}
    </div>
  );
}

import { useEffect, useRef } from 'react';
import Plotly from 'plotly.js-dist-min';
import { PlotlySpec } from '../../types';

interface PlotlyChartProps {
  spec: PlotlySpec;
}

export function PlotlyChart({ spec }: PlotlyChartProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current || !spec) return;

    // Purge any existing Plotly instance on container to prevent trace reuse or stale state
    Plotly.purge(containerRef.current);

    const isFullLap = spec.chart_type === 'full_lap_comparison';

    // Ensure layout uses dark HUD background #0B0F17
    const layout = {
      ...spec.layout,
      paper_bgcolor: '#0B0F17',
      plot_bgcolor: '#0B0F17',
      autosize: true,
      datarevision: Date.now(),
      hovermode: isFullLap ? 'x unified' : (spec.layout?.hovermode || 'closest'),
    };

    const config = {
      responsive: true,
      displayModeBar: isFullLap ? 'hover' : false,
      modeBarButtonsToRemove: ['lasso2d', 'select2d'],
      displaylogo: false,
      scrollZoom: isFullLap,
      ...(spec.config || {}),
    };

    Plotly.newPlot(containerRef.current, spec.data, layout, config);

    const handleResize = () => {
      if (containerRef.current) {
        Plotly.Plots.resize(containerRef.current);
      }
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      if (containerRef.current) {
        Plotly.purge(containerRef.current);
      }
    };
  }, [spec]);

  return (
    <div className="relative h-full w-full rounded-lg border border-[#1E293B] bg-[#0B0F17] p-2">
      <div ref={containerRef} className="h-full w-full min-h-[350px]" />
    </div>
  );
}

import { Activity, BarChart2 } from 'lucide-react';
import { PlotlySpec, EngineeringTrace } from '../../types';
import { PlotlyChart } from './PlotlyChart';
import { TrackMiniMap } from './TrackMiniMap';
import { SectorSummaryBar } from './SectorSummaryBar';
import { MetadataBar } from '../MetadataBar/MetadataBar';
import { TraceDrawer } from '../EngineeringTrace/TraceDrawer';

interface ChartStageProps {
  chart: PlotlySpec | null;
  minimap?: PlotlySpec | null;
  trace: EngineeringTrace | null;
}

export function ChartStage({ chart, minimap, trace }: ChartStageProps) {
  const rawDrivers = chart?.metadata?.drivers || [];
  const driverCodes = rawDrivers
    .map((d: any) => (typeof d === 'string' ? d : d.code || ''))
    .filter(Boolean)
    .join('-');

  const chartKey = chart
    ? `${chart.chart_type || 'chart'}_${chart.metadata?.year || ''}_${chart.metadata?.grand_prix || ''}_${driverCodes}_${chart.layout?.title?.text || ''}`
    : 'no_chart';

  return (
    <div className="flex h-full flex-col bg-[#0B0F17] p-4 overflow-y-auto space-y-3">
      {/* Top stage header */}
      <div className="flex h-10 items-center justify-between border-b border-[#1E293B] pb-2">
        <div className="flex items-center space-x-2">
          <BarChart2 className="h-4 w-4 text-[#E10600]" />
          <h2 className="font-mono text-xs uppercase tracking-wider text-white">
            Telemetry & Visual Analytics Stage
          </h2>
        </div>
        <div className="text-[11px] font-mono text-[#94A3B8]">
          HUD STANDARD: #0B0F17 • ZERO-HALLUCINATION
        </div>
      </div>

      {/* Metadata Bar for Active Chart */}
      {chart && <MetadataBar chart={chart} minimap={minimap || null} />}

      {/* Sector & Speed Trap Summary Bar for Full-Lap Overlays */}
      {chart?.chart_type === 'full_lap_comparison' && <SectorSummaryBar chart={chart} />}

      {/* Main visualization container */}
      <div className="flex-1 min-h-[420px]">
        {chart ? (
          minimap ? (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-3">
              <div className="lg:col-span-2">
                <PlotlyChart key={chartKey} spec={chart} />
              </div>
              <div className="lg:col-span-1">
                <TrackMiniMap key={`mini_${chartKey}`} spec={minimap} />
              </div>
            </div>
          ) : (
            <div className="h-full w-full">
              <PlotlyChart key={chartKey} spec={chart} />
            </div>
          )
        ) : (
          <div className="flex h-full flex-col items-center justify-center text-center p-8 text-[#64748B]">
            <Activity className="h-10 w-10 mb-3 text-[#1E293B]" />
            <p className="font-mono text-xs text-[#94A3B8]">
              Awaiting query execution...
            </p>
            <p className="mt-1 text-[11px] max-w-sm">
              Select a preset prompt or ask a Formula 1 question to render interactive Plotly charts, synchronized telemetry panels, and GPS track maps.
            </p>
          </div>
        )}
      </div>

      {/* Collapsible Engineering Trace Drawer */}
      <TraceDrawer trace={trace} />
    </div>
  );
}

