import React from 'react';
import { renderToString } from 'react-dom/server';
import { SectorSummaryBar } from './src/components/ChartStage/SectorSummaryBar';
import { MetadataBar } from './src/components/MetadataBar/MetadataBar';
import { ErrorBoundary } from './src/components/ErrorBoundary/ErrorBoundary';
import { ChartStage } from './src/components/ChartStage/ChartStage';

console.log('--- Starting Frontend Component Render Verification ---');

// 1. Real Full-Lap Telemetry Payload
const fullLapPayload = {
  chart_type: 'full_lap_comparison',
  layout: {
    title: { text: 'Full-Lap Telemetry — 2024 Monza' },
  },
  data: [
    { type: 'scatter', x: [0, 100, 200], y: [300, 310, 320], name: 'VER Speed' },
    { type: 'scatter', x: [0, 100, 200], y: [298, 305, 318], name: 'NOR Speed' },
  ],
  metadata: {
    domain: 'telemetry' as const,
    year: 2024,
    grand_prix: 'Italian Grand Prix',
    session_name: 'Qualifying',
    mode_label: 'Full-Lap Overlay • All Sectors',
    drivers: [
      { code: 'VER', name: 'Red Bull Racing', color: '#3671C6', compound: 'SOFT' },
      { code: 'NOR', name: 'McLaren', color: '#FF8000', compound: 'SOFT' },
    ],
    track_status: 'DRY',
    metrics: {
      sectors: {
        sector_1: { driver_a: 26.541, driver_b: 26.432, delta_s: -0.109, faster: 'NOR', boundary_m: 1600.0 },
        sector_2: { driver_a: 27.102, driver_b: 27.255, delta_s: 0.153, faster: 'VER', boundary_m: 3800.0 },
        sector_3: { driver_a: 25.891, driver_b: 25.912, delta_s: 0.021, faster: 'VER' },
      },
      speed_trap: {
        driver_a: 345.2,
        driver_b: 341.8,
        delta_kph: -3.4,
      },
      lap_times: {
        driver_a: 79.534,
        driver_b: 79.599,
        delta_s: 0.065,
        faster: 'VER',
      },
    },
    sector_summary: {
      sectors: {
        sector_1: { driver_a: 26.541, driver_b: 26.432, delta_s: -0.109, faster: 'NOR' },
      },
    },
  },
};

// Test 1: SectorSummaryBar render
try {
  const htmlSector = renderToString(<SectorSummaryBar chart={fullLapPayload} />);
  if (!htmlSector.includes('VER') || !htmlSector.includes('NOR')) {
    throw new Error('SectorSummaryBar did not render driver codes VER and NOR');
  }
  if (!htmlSector.includes('26.541s')) {
    throw new Error('SectorSummaryBar did not render sector 1 time');
  }
  console.log('✓ SectorSummaryBar rendered full-lap payload with 0 errors');
} catch (err) {
  console.error('FAILED SectorSummaryBar render:', err);
  process.exit(1);
}

// Test 2: MetadataBar with full-lap payload
try {
  const htmlMeta = renderToString(<MetadataBar chart={fullLapPayload} />);
  if (!htmlMeta.includes('VER') || !htmlMeta.includes('NOR') || !htmlMeta.includes('vs')) {
    throw new Error('MetadataBar did not render 2-driver badges with vs');
  }
  console.log('✓ MetadataBar rendered 2-driver comparison with 0 errors');
} catch (err) {
  console.error('FAILED MetadataBar render:', err);
  process.exit(1);
}

// Test 3: MetadataBar with single driver
try {
  const soloLecPayload = {
    ...fullLapPayload,
    metadata: {
      ...fullLapPayload.metadata,
      drivers: [{ code: 'LEC', name: 'Ferrari', color: '#E80020', compound: 'HARD' }],
    },
  };
  const htmlSolo = renderToString(<MetadataBar chart={soloLecPayload} />);
  if (!htmlSolo.includes('LEC')) {
    throw new Error('MetadataBar did not render solo LEC badge');
  }
  if (htmlSolo.includes('>vs<')) {
    throw new Error('MetadataBar rendered unexpected "vs" for solo driver');
  }
  console.log('✓ MetadataBar rendered single-driver analysis with 0 errors (no "vs")');
} catch (err) {
  console.error('FAILED MetadataBar solo render:', err);
  process.exit(1);
}

// Test 4: MetadataBar with historical SQL payload
try {
  const histPayload = {
    chart_type: 'bar',
    layout: { title: { text: 'Win Percentage' } },
    data: [{ type: 'bar', x: [50, 40], y: ['Senna', 'Prost'] }],
    metadata: {
      domain: 'historical' as const,
      year: 2024,
      grand_prix: 'Monza',
      session_name: 'Historical Records',
      mode_label: 'Historical Analytics • DuckDB',
      drivers: [],
      track_status: null,
    },
  };
  const htmlHist = renderToString(<MetadataBar chart={histPayload} />);
  if (!htmlHist.includes('HISTORICAL SQL • DUCKDB')) {
    throw new Error('MetadataBar did not render Historical SQL badge');
  }
  console.log('✓ MetadataBar rendered historical DuckDB payload with 0 errors');
} catch (err) {
  console.error('FAILED MetadataBar historical render:', err);
  process.exit(1);
}

// Test 5: ErrorBoundary handles throwing child without blank screen
try {
  const ThrowingComponent = () => {
    throw new Error('Simulated child render failure');
  };
  // suppress expected console.error from React
  const origError = console.error;
  console.error = () => {};
  const htmlError = renderToString(
    <ErrorBoundary fallbackTitle="Telemetry Stage Render Error">
      <ThrowingComponent />
    </ErrorBoundary>
  );
  console.error = origError;

  if (!htmlError.includes('Telemetry Stage Render Error') || !htmlError.includes('Reset Visualization Stage')) {
    throw new Error('ErrorBoundary did not render fallback UI card');
  }
  console.log('✓ ErrorBoundary caught simulated failure and rendered dark HUD error card with 0 app blanking');
} catch (err) {
  console.error('FAILED ErrorBoundary render test:', err);
  process.exit(1);
}

// Test 6: ChartStage mounting full-lap payload
try {
  const htmlStage = renderToString(
    <ChartStage chart={fullLapPayload} minimap={null} trace={null} />
  );
  if (!htmlStage.includes('Official Sector Splits & Speed Trap Summary')) {
    throw new Error('ChartStage did not render SectorSummaryBar');
  }
  if (!htmlStage.includes('Telemetry & Visual Analytics Stage')) {
    throw new Error('ChartStage did not render header');
  }
  console.log('✓ ChartStage rendered full-lap comparison with 0 errors');
} catch (err) {
  console.error('FAILED ChartStage full-lap render:', err);
  process.exit(1);
}

console.log('--- ALL FRONTEND RENDER VERIFICATIONS PASSED CLEANLY ---');

