1: import { useState, useCallback } from 'react';
2: import { ChatMessage, EngineeringTrace, PlotlySpec } from '../types';
3: 
4: interface UseSSEStreamReturn {
5:   messages: ChatMessage[];
6:   currentStatus: string | null;
7:   currentTrace: EngineeringTrace | null;
8:   currentChart: PlotlySpec | null;
9:   currentMinimap: PlotlySpec | null;
10:   isStreaming: boolean;
11:   sessionId: string | null;
12:   sendMessage: (text: string) => Promise<void>;
13:   resetChat: () => void;
14: }
15: 
16: export function useSSEStream(token?: string | null): UseSSEStreamReturn {
17:   const [messages, setMessages] = useState<ChatMessage[]>([]);
18:   const [currentStatus, setCurrentStatus] = useState<string | null>(null);
19:   const [currentTrace, setCurrentTrace] = useState<EngineeringTrace | null>(null);
20:   const [currentChart, setCurrentChart] = useState<PlotlySpec | null>(null);
21:   const [currentMinimap, setCurrentMinimap] = useState<PlotlySpec | null>(null);
22:   const [isStreaming, setIsStreaming] = useState(false);
23:   const [sessionId, setSessionId] = useState<string | null>(null);
24: 
25:   const sendMessage = useCallback(
26:     async (text: string) => {
27:       if (!text.trim() || isStreaming) return;
28: 
29:       const userMsg: ChatMessage = {
30:         id: `usr_${Date.now()}`,
31:         role: 'user',
32:         content: text.trim(),
33:         timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
34:       };
35: 
36:       setMessages((prev) => [...prev, userMsg]);
37:       setIsStreaming(true);
38:       setCurrentChart(null);
39:       setCurrentMinimap(null);
40:       setCurrentTrace(null);
41:       setCurrentStatus('Initializing connection to Pit Wall...');
42: 
43:       const assistantMsgId = `ast_${Date.now()}`;
44:       let accumulatedText = '';
45: 
46:       try {
47:         const headers: Record<string, string> = {
48:           'Content-Type': 'application/json',
49:         };
50:         if (token) {
51:           headers['Authorization'] = `Bearer ${token}`;
52:         }
53: 
54:         const res = await fetch('/api/chat/stream', {
55:           method: 'POST',
56:           headers,
57:           body: JSON.stringify({
58:             message: text.trim(),
59:             session_id: sessionId,
60:           }),
61:         });
62: 
63:         if (!res.ok) {
64:           throw new Error(`HTTP ${res.status}: Failed to initiate stream`);
65:         }
66: 
67:         const reader = res.body?.getReader();
68:         if (!reader) throw new Error('ReadableStream not available');
69: 
70:         const decoder = new TextDecoder('utf-8');
71:         let buffer = '';
72: 
73:         while (true) {
74:           const { value, done } = await reader.read();
75:           if (done) break;
76: 
77:           buffer += decoder.decode(value, { stream: true });
78:           const frames = buffer.split('\n\n');
79:           buffer = frames.pop() || '';
80: 
81:           for (const frame of frames) {
82:             if (!frame.trim()) continue;
83: 
84:             const lines = frame.split('\n');
85:             let eventType = 'message';
86:             let dataStr = '';
87: 
88:             for (const line of lines) {
89:               if (line.startsWith('event: ')) {
90:                 eventType = line.slice(7).trim();
91:               } else if (line.startsWith('data: ')) {
92:                 dataStr = line.slice(6).trim();
93:               }
94:             }
95: 
96:             if (!dataStr) continue;
97: 
98:             try {
99:               const data = JSON.parse(dataStr);
100: 
101:               switch (eventType) {
102:                 case 'session':
103:                   if (data.session_id) setSessionId(data.session_id);
104:                   break;
105: 
106:                 case 'status':
107:                   setCurrentStatus(data.detail || data.step || data.message);
108:                   break;
109: 
110:                 case 'text':
111:                   if (data.delta) {
112:                     accumulatedText += data.delta;
113:                     // Clear the status pill as soon as the first text chunk arrives
114:                     setCurrentStatus(null);
115:                     setMessages((prev) => {
116:                       const existing = prev.find((m) => m.id === assistantMsgId);
117:                       if (existing) {
118:                         return prev.map((m) =>
119:                           m.id === assistantMsgId
120:                             ? { ...m, content: accumulatedText, isStreaming: true }
121:                             : m
122:                         );
123:                       } else {
124:                         return [
125:                           ...prev,
126:                           {
127:                             id: assistantMsgId,
128:                             role: 'assistant',
129:                             content: accumulatedText,
130:                             timestamp: new Date().toLocaleTimeString([], {
131:                               hour: '2-digit',
132:                               minute: '2-digit',
133:                             }),
134:                             isStreaming: true,
135:                           },
136:                         ];
137:                       }
138:                     });
139:                   }
140:                   break;
141: 
142:                 case 'chart':
143:                   if (
144:                     data &&
145:                     (data.viz_type ||
146:                       data.spec ||
147:                       data.figure ||
148:                       data.kpi_card ||
149:                       data.data_table ||
150:                       data.web_intelligence_card)
151:                   ) {
152:                     const resolvedMeta = data.metadata || data.spec?.metadata || {};
153:                     const resolvedVizType =
154:                       data.viz_type || data.spec?.viz_type || data.chart_type || 'historical_sql';
155:                     const resolvedTitle = data.title || data.spec?.title || data.caption;
156: 
157:                     if (
158:                       resolvedVizType === 'web_intelligence_card' ||
159:                       data.chart_type === 'web_intelligence_card' ||
160:                       !!data.web_intelligence_card ||
161:                       !!data.spec?.web_intelligence_card
162:                     ) {
163:                       setCurrentChart({
164:                         viz_type: 'web_intelligence_card',
165:                         chart_type: 'web_intelligence_card',
166:                         title: resolvedTitle,
167:                         web_intelligence_card:
168:                           data.web_intelligence_card ||
169:                           data.spec?.web_intelligence_card ||
170:                           data.spec?.web_card ||
171:                           data.spec,
172:                         metadata: resolvedMeta,
173:                       });
174:                       setCurrentMinimap(null);
175:                     } else if (
176:                       resolvedVizType === 'kpi_card' ||
177:                       data.chart_type === 'kpi_card' ||
178:                       !!data.kpi_card ||
179:                       !!data.spec?.kpi_card
180:                     ) {
181:                       setCurrentChart({
182:                         viz_type: 'kpi_card',
183:                         chart_type: 'kpi_card',
184:                         title: resolvedTitle,
185:                         kpi_card: data.kpi_card || data.spec?.kpi_card,
186:                         metadata: resolvedMeta,
187:                       });
188:                       setCurrentMinimap(null);
189:                     } else if (
190:                       resolvedVizType === 'data_table' ||
191:                       data.chart_type === 'data_table' ||
192:                       !!data.data_table ||
193:                       !!data.spec?.data_table
194:                     ) {
195:                       setCurrentChart({
196:                         viz_type: 'data_table',
197:                         chart_type: 'data_table',
198:                         title: resolvedTitle,
199:                         data_table: data.data_table || data.spec?.data_table,
200:                         metadata: resolvedMeta,
201:                       });
202:                       setCurrentMinimap(null);
203:                     } else if (
204:                       resolvedVizType === 'track_minimap' ||
205:                       data.chart_type === 'track_minimap'
206:                     ) {
207:                       const miniFig = data.figure || data.spec || {};
208:                       setCurrentMinimap({
209:                         ...miniFig,
210:                         viz_type: 'track_minimap',
211:                         chart_type: 'track_minimap',
212:                         metadata: resolvedMeta,
213:                       });
214:                     } else {
215:                       const figPayload = data.figure || data.spec || {};
216:                       setCurrentChart({
217:                         ...figPayload,
218:                         viz_type: resolvedVizType,
219:                         chart_type: data.chart_type,
220:                         title: resolvedTitle,
221:                         metadata: resolvedMeta,
222:                       });
223:                       if (
224:                         resolvedVizType !== 'corner_telemetry' &&
225:                         data.chart_type !== 'corner_comparison'
226:                       ) {
227:                         setCurrentMinimap(null);
228:                       }
229:                     }
230:                   }
231:                   break;
232: 
233:                 case 'trace':
234:                   setCurrentTrace(data);
235:                   break;
236: 
237:                 case 'error':
238:                   const errorDetail = data.message || data.error || 'Unknown telemetry error';
239:                   setCurrentStatus(null);
240:                   accumulatedText += (accumulatedText ? '\n\n' : '') + `⚠️ **PitWall Error**: ${errorDetail}`;
241:                   setMessages((prev) => {
242:                     const existing = prev.find((m) => m.id === assistantMsgId);
243:                     if (existing) {
244:                       return prev.map((m) =>
245:                         m.id === assistantMsgId
246:                           ? { ...m, content: accumulatedText, isStreaming: false }
247:                           : m
248:                       );
249:                     } else {
250:                       return [
251:                         ...prev,
252:                         {
253:                           id: assistantMsgId,
254:                           role: 'assistant',
255:                           content: accumulatedText,
256:                           timestamp: new Date().toLocaleTimeString([], {
257:                             hour: '2-digit',
258:                             minute: '2-digit',
259:                           }),
260:                           isStreaming: false,
261:                         },
262:                       ];
263:                     }
264:                   });
265:                   break;
266: 
267:                 case 'done':
268:                   setCurrentStatus(null);
269:                   setMessages((prev) => {
270:                     const existing = prev.find((m) => m.id === assistantMsgId);
271:                     if (!existing && !accumulatedText) {
272:                       return [
273:                         ...prev,
274:                         {
275:                           id: assistantMsgId,
276:                           role: 'assistant',
277:                           content: '⚠️ **PitWall Notice**: Query completed with no telemetry commentary.',
278:                           timestamp: new Date().toLocaleTimeString([], {
279:                             hour: '2-digit',
280:                             minute: '2-digit',
281:                           }),
282:                           isStreaming: false,
283:                         },
284:                       ];
285:                     }
286:                     return prev.map((m) =>
287:                       m.id === assistantMsgId ? { ...m, isStreaming: false } : m
288:                     );
289:                   });
290:                   break;
291:               }
292:             } catch (jsonErr) {
293:               console.warn('Failed to parse SSE JSON chunk:', dataStr, jsonErr);
294:             }
295:           }
296:         }
297:       } catch (err: any) {
298:         console.error('SSE streaming error:', err);
299:         setMessages((prev) => [
300:           ...prev,
301:           {
302:             id: `err_${Date.now()}`,
303:             role: 'assistant',
304:             content: `Telemetry error: ${err.message || 'Connection lost to PitWall server.'}`,
305:             timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
306:             isStreaming: false,
307:           },
308:         ]);
309:       } finally {
310:         setMessages((prev) =>
311:           prev.map((m) =>
312:             m.id === assistantMsgId ? { ...m, isStreaming: false } : m
313:           )
314:         );
315:         setIsStreaming(false);
316:         setCurrentStatus(null);
317:       }
318:     },
319:     [isStreaming, sessionId, token]
320:   );
321: 
322:   const resetChat = useCallback(() => {
323:     setMessages([]);
324:     setCurrentStatus(null);
325:     setCurrentTrace(null);
326:     setCurrentChart(null);
327:     setCurrentMinimap(null);
328:     setSessionId(null);
329:   }, []);
330: 
331:   return {
332:     messages,
333:     currentStatus,
334:     currentTrace,
335:     currentChart,
336:     currentMinimap,
337:     isStreaming,
338:     sessionId,
339:     sendMessage,
340:     resetChat,
341:   };
342: }

