1: import { useEffect, useRef } from 'react';
2: import Plotly from 'plotly.js-dist-min';
3: import { PlotlySpec } from '../../types';
4: 
5: interface PlotlyChartProps {
6:   spec: PlotlySpec;
7: }
8: 
9: export function PlotlyChart({ spec }: PlotlyChartProps) {
10:   const containerRef = useRef<HTMLDivElement>(null);
11: 
12:   useEffect(() => {
13:     if (!containerRef.current || !spec) return;
14: 
15:     // Purge any existing Plotly instance on container to prevent trace reuse or stale state
16:     Plotly.purge(containerRef.current);
17: 
18:     const isFullLap = spec.chart_type === 'full_lap_comparison';
19: 
20:     // Ensure layout uses dark HUD background #0B0F17
21:     const layout = {
22:       ...spec.layout,
23:       paper_bgcolor: '#0B0F17',
24:       plot_bgcolor: '#0B0F17',
25:       autosize: true,
26:       datarevision: Date.now(),
27:       hovermode: isFullLap ? 'x unified' : (spec.layout?.hovermode || 'closest'),
28:     };
29: 
30:     const config = {
31:       responsive: true,
32:       displayModeBar: isFullLap ? 'hover' : false,
33:       modeBarButtonsToRemove: ['lasso2d', 'select2d'],
34:       displaylogo: false,
35:       scrollZoom: isFullLap,
36:       ...(spec.config || {}),
37:     };
38: 
39:     const plotData = Array.isArray(spec.data) ? spec.data : [];
40: 
41:     try {
42:       Plotly.newPlot(containerRef.current, plotData, layout, config);
43:     } catch (err) {
44:       console.error('Plotly.newPlot failed to render:', err);
45:     }
46: 
47:     const handleResize = () => {
48:       if (containerRef.current) {
49:         Plotly.Plots.resize(containerRef.current);
50:       }
51:     };
52: 
53:     window.addEventListener('resize', handleResize);
54: 
55:     return () => {
56:       window.removeEventListener('resize', handleResize);
57:       if (containerRef.current) {
58:         Plotly.purge(containerRef.current);
59:       }
60:     };
61:   }, [spec]);
62: 
63:   return (
64:     <div className="relative h-full w-full rounded-lg border border-[#1E293B] bg-[#0B0F17] p-2">
65:       <div ref={containerRef} className="h-full w-full min-h-[350px]" />
66:     </div>
67:   );
68: }

