import { useState } from 'react';
import {
  ChevronDown,
  ChevronUp,
  Copy,
  Check,
  Terminal,
  Clock,
  ArrowRight,
  Layers,
  ExternalLink,
} from 'lucide-react';
import { EngineeringTrace } from '../../types';

interface TraceDrawerProps {
  trace?: EngineeringTrace | null;
}

export function TraceDrawer({ trace }: TraceDrawerProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [copied, setCopied] = useState(false);

  if (!trace) {
    return null;
  }

  const hops = trace.a2a_hops || [];
  const groundingSources = trace.grounding_sources || [];

  const isTelemetry =
    trace.data_domain === 'telemetry' ||
    !!trace.telemetry_params ||
    !!(trace as any).strategy_params;
  const isResearch = trace.data_domain === 'research' || groundingSources.length > 0;
  const params = trace.telemetry_params || (trace as any).strategy_params;

  const handleCopy = () => {
    const textToCopy = trace.query || (params ? JSON.stringify(params, null, 2) : '');
    if (textToCopy) {
      navigator.clipboard.writeText(textToCopy);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const getProviderShortTag = () => {
    if (trace.provider) return trace.provider;
    if (isResearch) return 'gemini';
    if (isTelemetry) return 'openf1';
    return 'duckdb';
  };

  const getProviderLabel = () => {
    if (trace.provider === 'ollama_fallback') return 'Ollama Fallback (qwen3.5)';
    if (trace.provider === 'cache') return isResearch ? 'Research Disk Cache' : 'Persistent Cache';
    if (trace.provider === 'gemini') {
      if (isResearch) return 'Gemini Search Grounding';
      if (isTelemetry) return 'OpenF1 + Gemini';
      return 'DuckDB + Gemini';
    }
    if (isResearch) return 'Gemini Search Grounding';
    if (isTelemetry) return 'OpenF1 REST API';
    return 'DuckDB Read-Only';
  };

  const providerTag = getProviderShortTag();
  const providerColorClass =
    providerTag === 'ollama_fallback'
      ? 'border-amber-500/30 bg-amber-950/30 text-amber-400'
      : providerTag === 'cache'
      ? 'border-cyan-500/30 bg-cyan-950/30 text-cyan-400'
      : 'border-emerald-500/30 bg-emerald-950/30 text-emerald-400';

  return (
    <div className="rounded-lg border border-[#1E293B] bg-[#121824]/90 shadow-sm">
      {/* Compact single-line toggle bar */}
      <button
        type="button"
        onClick={() => setIsOpen((prev) => !prev)}
        className="flex w-full items-center justify-between gap-2 px-3.5 py-2 text-xs font-mono text-[#94A3B8] hover:bg-[#1A2234] transition-colors rounded-lg"
      >
        <div className="flex flex-wrap items-center gap-2 min-w-0">
          <Terminal className="h-3.5 w-3.5 text-[#E10600] shrink-0" />
          <span className="font-semibold text-[#E2E8F0] uppercase tracking-wider text-[11px]">
            Engineering Trace
          </span>
          <span className="rounded bg-[#1E293B] px-1.5 py-0.5 text-[10px] text-emerald-400">
            {trace.data_domain.toUpperCase()}
          </span>
          {hops.length > 0 && (
            <span className="inline-flex items-center space-x-1 rounded border border-[#1E293B] bg-[#0B0F17] px-1.5 py-0.5 text-[10px] text-[#CBD5E1]">
              <Layers className="h-2.5 w-2.5 text-cyan-400" />
              <span>
                {hops.length} {hops.length === 1 ? 'hop' : 'hops'}
              </span>
            </span>
          )}
          <span className={`rounded border px-1.5 py-0.5 text-[10px] ${providerColorClass}`}>
            {providerTag}
          </span>
        </div>

        <div className="flex items-center space-x-2.5 shrink-0">
          {trace.execution_time_ms !== undefined && (
            <span className="flex items-center space-x-1 text-[11px] text-[#94A3B8]">
              <Clock className="h-3 w-3" />
              <span>{trace.execution_time_ms} ms</span>
            </span>
          )}
          {isOpen ? (
            <ChevronUp className="h-4 w-4 text-[#94A3B8]" />
          ) : (
            <ChevronDown className="h-4 w-4 text-[#94A3B8]" />
          )}
        </div>
      </button>

      {isOpen && (
        <div className="border-t border-[#1E293B] p-4 space-y-3 font-mono text-xs">
          {/* Metadata badges */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
            <div className="rounded border border-[#1E293B] bg-[#0B0F17] p-2">
              <span className="text-[10px] text-[#64748B] block">DATA DOMAIN</span>
              <span className="text-white font-medium">{trace.data_domain}</span>
            </div>
            <div className="rounded border border-[#1E293B] bg-[#0B0F17] p-2">
              <span className="text-[10px] text-[#64748B] block">
                {isResearch ? 'SOURCES' : isTelemetry ? 'SAMPLES / ROWS' : 'ROW COUNT'}
              </span>
              <span className="text-white font-medium">
                {isResearch
                  ? groundingSources.length
                  : trace.row_count !== undefined
                  ? trace.row_count
                  : params?.clean_lap_counts
                  ? (Object.values(params.clean_lap_counts) as number[]).reduce(
                      (a: number, b: number) => a + b,
                      0
                    )
                  : trace.interpolated_points !== undefined
                  ? trace.interpolated_points
                  : 'N/A'}
              </span>
            </div>
            <div className="rounded border border-[#1E293B] bg-[#0B0F17] p-2">
              <span className="text-[10px] text-[#64748B] block">CONFIDENCE</span>
              <span className="text-emerald-400 font-medium">
                {(trace.confidence * 100).toFixed(0)}%
              </span>
            </div>
            <div className="rounded border border-[#1E293B] bg-[#0B0F17] p-2">
              <span className="text-[10px] text-[#64748B] block">PROVIDER</span>
              <span
                className={`font-medium ${
                  trace.provider === 'ollama_fallback'
                    ? 'text-amber-400'
                    : trace.provider === 'cache'
                    ? 'text-cyan-400'
                    : 'text-white'
                }`}
              >
                {getProviderLabel()}
              </span>
            </div>
          </div>

          {/* A2A Multi-Agent Hop Trace */}
          {hops.length > 0 && (
            <div className="rounded border border-[#1E293B] bg-[#0B0F17] p-3 space-y-2">
              <div className="flex items-center justify-between border-b border-[#1E293B] pb-1.5">
                <div className="flex items-center space-x-2 text-cyan-400">
                  <Layers className="h-3.5 w-3.5" />
                  <span className="font-semibold text-white uppercase tracking-wider text-[11px]">
                    A2A Specialist Hop Trace ({hops.length} hops)
                  </span>
                </div>
                <span className="text-[10px] text-[#64748B]">Google ADK + A2A Routing</span>
              </div>

              {/* Hop Sequence Breadcrumbs */}
              <div className="flex flex-wrap items-center gap-1.5 pt-1">
                <span className="rounded bg-[#1E293B] px-2 py-1 text-[11px] font-semibold text-white">
                  PitWallEngineer
                </span>
                {hops.map((hop, idx) => (
                  <div key={idx} className="flex items-center space-x-1.5">
                    <ArrowRight className="h-3 w-3 text-[#64748B]" />
                    <div
                      className={`flex items-center space-x-1.5 rounded border px-2 py-1 text-[11px] ${
                        hop.status === 'success'
                          ? 'border-emerald-500/30 bg-[#121824] text-emerald-400'
                          : 'border-rose-500/30 bg-rose-950/30 text-rose-400'
                      }`}
                    >
                      <span className="font-semibold">{hop.agent_name}</span>
                      <span className="text-[10px] text-[#64748B]">({hop.duration_ms}ms)</span>
                      {hop.dataset_id && (
                        <span className="rounded bg-[#0B0F17] px-1 py-0.2 text-[9px] text-cyan-300 font-mono">
                          {hop.dataset_id.slice(0, 8)}…
                        </span>
                      )}
                    </div>
                  </div>
                ))}
              </div>

              {/* Dataset ID if present */}
              {trace.dataset_id && (
                <div className="flex items-center justify-between pt-1 text-[10px] text-[#64748B] border-t border-[#1E293B]/40">
                  <span>ARTIFACT DATASET ID:</span>
                  <span className="font-mono text-cyan-400">{trace.dataset_id}</span>
                </div>
              )}
            </div>
          )}

          {/* Telemetry provenance badges */}
          {params && (
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 pt-1 border-t border-[#1E293B]/60">
              {params.session_key && (
                <div className="rounded border border-[#1E293B] bg-[#0B0F17] p-2">
                  <span className="text-[10px] text-[#64748B] block">SESSION KEY</span>
                  <span className="text-cyan-400 font-medium">#{params.session_key}</span>
                </div>
              )}
              {params.interpolation_method && (
                <div className="rounded border border-[#1E293B] bg-[#0B0F17] p-2">
                  <span className="text-[10px] text-[#64748B] block">INTERPOLATION</span>
                  <span className="text-[#E2E8F0] font-medium">{params.interpolation_method}</span>
                </div>
              )}
              {params.lap_numbers && (
                <div className="rounded border border-[#1E293B] bg-[#0B0F17] p-2">
                  <span className="text-[10px] text-[#64748B] block">DRIVER LAPS</span>
                  <span className="text-emerald-400 font-medium">
                    {Array.isArray(params.lap_numbers)
                      ? params.lap_numbers.join(' | ')
                      : Object.entries(params.lap_numbers)
                          .map(([d, l]) => `${d}: L${l}`)
                          .join(' | ')}
                  </span>
                </div>
              )}
              {params.sector_boundaries_m && (
                <div className="rounded border border-[#1E293B] bg-[#0B0F17] p-2">
                  <span className="text-[10px] text-[#64748B] block">SECTORS</span>
                  <span className="text-amber-400 font-medium">
                    S1: {Math.round(params.sector_boundaries_m[0])}m | S2:{' '}
                    {Math.round(params.sector_boundaries_m[1])}m
                  </span>
                </div>
              )}
              {params.stint_counts && (
                <div className="rounded border border-[#1E293B] bg-[#0B0F17] p-2">
                  <span className="text-[10px] text-[#64748B] block">STINTS</span>
                  <span className="text-emerald-400 font-medium">
                    {Object.entries(params.stint_counts)
                      .map(([d, s]) => `${d}: ${s}S`)
                      .join(' | ')}
                  </span>
                </div>
              )}
              {params.clean_lap_counts && (
                <div className="rounded border border-[#1E293B] bg-[#0B0F17] p-2">
                  <span className="text-[10px] text-[#64748B] block">CLEAN LAPS</span>
                  <span className="text-amber-400 font-medium">
                    {Object.entries(params.clean_lap_counts)
                      .map(([d, c]) => {
                        const out = params.excluded_lap_counts
                          ? params.excluded_lap_counts[d]
                          : undefined;
                        return out !== undefined ? `${d}: ${c}L (${out} filtered)` : `${d}: ${c}L`;
                      })
                      .join(' | ')}
                  </span>
                </div>
              )}
              {params.pit_stop_laps && (
                <div className="rounded border border-[#1E293B] bg-[#0B0F17] p-2">
                  <span className="text-[10px] text-[#64748B] block">PIT LAPS</span>
                  <span className="text-rose-400 font-medium">
                    {Object.entries(params.pit_stop_laps)
                      .map(([d, p]) => `${d}: L${(p as number[]).join(',')}`)
                      .join(' | ')}
                  </span>
                </div>
              )}
            </div>
          )}

          {/* Grounding Sources (for Research inquiries) */}
          {groundingSources.length > 0 && (
            <div className="space-y-2 pt-1 border-t border-[#1E293B]/60">
              <div className="flex items-center justify-between text-[#94A3B8]">
                <span className="text-[10px] uppercase tracking-wider text-[#64748B]">
                  Google Search Grounding Sources ({groundingSources.length}):
                </span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-1.5">
                {groundingSources.map((src, idx) => (
                  <a
                    key={idx}
                    href={src.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center justify-between rounded border border-[#1E293B] bg-[#0B0F17] px-2.5 py-1.5 text-[11px] text-[#94A3B8] hover:text-white hover:border-cyan-500/50 transition-colors"
                  >
                    <span className="truncate pr-2">{src.title || src.url}</span>
                    <ExternalLink className="h-3 w-3 shrink-0 text-cyan-400" />
                  </a>
                ))}
              </div>
            </div>
          )}

          {/* Exact SQL Query or Telemetry Parameters */}
          {trace.query ? (
            <div>
              <div className="flex items-center justify-between pb-1 text-[#94A3B8]">
                <span className="text-[10px] uppercase tracking-wider text-[#64748B]">
                  Exact Ground-Truth SQL Statement:
                </span>
                <button
                  type="button"
                  onClick={handleCopy}
                  className="flex items-center space-x-1 text-[11px] hover:text-white transition-colors"
                >
                  {copied ? (
                    <Check className="h-3 w-3 text-emerald-400" />
                  ) : (
                    <Copy className="h-3 w-3" />
                  )}
                  <span>{copied ? 'Copied' : 'Copy SQL'}</span>
                </button>
              </div>
              <pre className="overflow-x-auto rounded bg-[#0B0F17] p-3 text-[11px] text-emerald-400 border border-[#1E293B] leading-relaxed whitespace-pre-wrap">
                {trace.query}
              </pre>
            </div>
          ) : params ? (
            <div>
              <div className="flex items-center justify-between pb-1 text-[#94A3B8]">
                <span className="text-[10px] uppercase tracking-wider text-[#64748B]">
                  {trace.strategy_params || (params && params.stint_counts)
                    ? 'Ground-Truth Tyre Stint & Strategy Parameters:'
                    : 'Ground-Truth Telemetry Trace Parameters:'}
                </span>
                <button
                  type="button"
                  onClick={handleCopy}
                  className="flex items-center space-x-1 text-[11px] hover:text-white transition-colors"
                >
                  {copied ? (
                    <Check className="h-3 w-3 text-emerald-400" />
                  ) : (
                    <Copy className="h-3 w-3" />
                  )}
                  <span>{copied ? 'Copied' : 'Copy Parameters'}</span>
                </button>
              </div>
              <pre className="overflow-x-auto rounded bg-[#0B0F17] p-3 text-[11px] text-cyan-300 border border-[#1E293B] leading-relaxed whitespace-pre-wrap">
                {JSON.stringify(params, null, 2)}
              </pre>
            </div>
          ) : null}

          {trace.notes && (
            <p className="text-[11px] text-[#94A3B8] italic">Note: {trace.notes}</p>
          )}
        </div>
      )}
    </div>
  );
}

import { Gauge, Layers, Timer, Trophy, ArrowUpRight } from 'lucide-react';

interface WelcomeHeroProps {
  onSelect: (prompt: string) => void;
  disabled?: boolean;
}

const STARTER_CARDS = [
  {
    category: 'Corner Telemetry',
    title: 'Copse Entry & Exit Delta',
    prompt: 'Compare Verstappen and Norris through Copse at 2024 British GP Qualifying',
    icon: Gauge,
    accent: 'text-[#38BDF8] border-[#38BDF8]/30 bg-[#38BDF8]/10',
    hoverBorder: 'hover:border-[#38BDF8]/60',
  },
  {
    category: 'Full-Lap Overlay',
    title: 'Monza Qualifying Pace Map',
    prompt: 'Overlay Verstappen vs Norris full lap at 2024 Italian GP Qualifying',
    icon: Layers,
    accent: 'text-emerald-400 border-emerald-500/30 bg-emerald-500/10',
    hoverBorder: 'hover:border-emerald-500/60',
  },
  {
    category: 'Tyre Stints',
    title: 'Monza One-Stop vs Two-Stop',
    prompt: 'Compare Leclerc vs Piastri tyre degradation and stint strategy at 2024 Italian GP',
    icon: Timer,
    accent: 'text-amber-400 border-amber-500/30 bg-amber-500/10',
    hoverBorder: 'hover:border-amber-500/60',
  },
  {
    category: 'Historical & Research',
    title: 'Race Results & Records',
    prompt: 'Who won the 2023 Bahrain Grand Prix?',
    icon: Trophy,
    accent: 'text-[#E10600] border-[#E10600]/30 bg-[#E10600]/10',
    hoverBorder: 'hover:border-[#E10600]/60',
  },
];

export function WelcomeHero({ onSelect, disabled }: WelcomeHeroProps) {
  return (
    <div className="mx-auto flex w-full max-w-3xl flex-1 flex-col items-center justify-center px-4 py-12">
      {/* PitWall Hero Identity */}
      <div className="mb-8 flex flex-col items-center text-center">
        <div className="mb-4 flex items-center space-x-2.5 rounded-full border border-[#1E293B] bg-[#121824] px-3.5 py-1.5 shadow-sm">
          <span className="flex h-5 w-5 items-center justify-center rounded bg-[#E10600] font-mono text-[10px] font-black text-white">
            F1
          </span>
          <span className="font-mono text-xs font-semibold tracking-wider text-[#E2E8F0]">
            PITWALL AI RACE ENGINEER
          </span>
        </div>

        <h1 className="text-2xl sm:text-3xl font-bold tracking-tight text-white">
          What are we analyzing on track today?
        </h1>
        <p className="mt-2.5 max-w-xl text-sm text-[#94A3B8] leading-relaxed">
          Deterministic Formula 1 analytics spanning 1950–2024+ DuckDB records, 2023+ OpenF1 car
          telemetry, tyre stint degradation, and grounded web intelligence.
        </p>
      </div>

      {/* 2x2 Starter Prompt Cards */}
      <div className="grid w-full grid-cols-1 sm:grid-cols-2 gap-3">
        {STARTER_CARDS.map((card) => {
          const Icon = card.icon;
          return (
            <button
              key={card.prompt}
              type="button"
              disabled={disabled}
              onClick={() => onSelect(card.prompt)}
              className={`group flex flex-col justify-between rounded-xl border border-[#1E293B] bg-[#121824]/85 p-4 text-left transition-all hover:bg-[#161F30] ${card.hoverBorder} disabled:opacity-50`}
            >
              <div className="flex items-center justify-between mb-2.5">
                <div className="flex items-center space-x-2">
                  <span className={`rounded-md border p-1.5 ${card.accent}`}>
                    <Icon className="h-3.5 w-3.5" />
                  </span>
                  <span className="font-mono text-[11px] font-semibold uppercase tracking-wider text-[#CBD5E1]">
                    {card.category}
                  </span>
                </div>
                <ArrowUpRight className="h-3.5 w-3.5 text-[#64748B] transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5 group-hover:text-white" />
              </div>

              <div>
                <div className="text-xs font-semibold text-white mb-1">{card.title}</div>
                <p className="text-xs text-[#94A3B8] leading-relaxed line-clamp-2">
                  {card.prompt}
                </p>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

import { Zap, Gauge, Layers, Timer, X } from 'lucide-react';

interface PresetPromptsProps {
  onSelect: (prompt: string) => void;
  onClose?: () => void;
  disabled?: boolean;
}

const PRESET_GROUPS = [
  {
    label: 'Tyre Degradation & Strategy (2023+)',
    icon: Timer,
    iconColor: 'text-amber-400',
    hoverBorder: 'hover:border-amber-400',
    queries: [
      'Compare Leclerc vs Piastri tyre degradation and stint strategy at 2024 Italian GP',
      'Show tyre degradation and race pace for Leclerc at Monza 2024',
    ],
  },
  {
    label: 'Full-Lap Telemetry Overlays (2023+)',
    icon: Layers,
    iconColor: 'text-emerald-400',
    hoverBorder: 'hover:border-emerald-500',
    queries: [
      'Overlay Verstappen vs Norris full lap at 2024 Italian GP Qualifying',
      'Overlay Verstappen vs Leclerc full lap at 2024 Belgian GP Qualifying',
    ],
  },
  {
    label: 'Corner Telemetry Comparisons (2023+)',
    icon: Gauge,
    iconColor: 'text-[#38BDF8]',
    hoverBorder: 'hover:border-[#38BDF8]',
    queries: [
      'Compare Verstappen and Norris through Copse at 2024 British GP Qualifying',
      'Compare Leclerc and Hamilton through Eau Rouge at 2023 Belgian GP Qualifying',
      'Compare Alonso and Piastri through 130R at 2024 Japanese GP Qualifying',
    ],
  },
  {
    label: 'Historical F1 Analytics (1950–2024+)',
    icon: Zap,
    iconColor: 'text-[#E10600]',
    hoverBorder: 'hover:border-[#E10600]',
    queries: [
      'Who won the 2023 Bahrain Grand Prix?',
      'Show me Lewis Hamilton podium finishes per season',
      'Monza highest win percentage with >=5 starts',
      '2023 Drivers Championship standings top 10',
    ],
  },
];

export function PresetPrompts({ onSelect, onClose, disabled }: PresetPromptsProps) {
  return (
    <div className="w-full max-h-[60vh] overflow-y-auto rounded-xl border border-[#1E293B] bg-[#0E1420]/98 p-4 shadow-2xl backdrop-blur-md space-y-3">
      <div className="flex items-center justify-between border-b border-[#1E293B] pb-2">
        <div className="flex items-center space-x-2">
          <Zap className="h-3.5 w-3.5 text-[#E10600]" />
          <span className="font-mono text-xs font-semibold uppercase tracking-wider text-white">
            Quick Engineering Prompts
          </span>
        </div>
        {onClose && (
          <button
            type="button"
            onClick={onClose}
            aria-label="Close prompts menu"
            className="rounded p-1 text-[#94A3B8] hover:bg-[#1E293B] hover:text-white transition-colors"
          >
            <X className="h-3.5 w-3.5" />
          </button>
        )}
      </div>

      {PRESET_GROUPS.map((group) => {
        const Icon = group.icon;
        return (
          <div key={group.label}>
            <div className="flex items-center space-x-1.5 text-[10px] font-mono uppercase tracking-wider text-[#94A3B8] mb-1.5">
              <Icon className={`h-3 w-3 ${group.iconColor}`} />
              <span>{group.label}</span>
            </div>
            <div className="flex flex-wrap gap-1.5">
              {group.queries.map((query) => (
                <button
                  key={query}
                  type="button"
                  disabled={disabled}
                  onClick={() => {
                    onSelect(query);
                    onClose?.();
                  }}
                  className={`rounded-md border border-[#1E293B] bg-[#121824] px-2.5 py-1.5 text-left text-xs font-mono text-[#E2E8F0] transition-colors ${group.hoverBorder} hover:text-white disabled:opacity-50`}
                >
                  {query}
                </button>
              ))}
            </div>
          </div>
        );
      })}
    </div>
  );
}

import { Loader2 } from 'lucide-react';
import { ChatMessage } from '../../types';
import { ChartStage } from '../ChartStage/ChartStage';
import { MessageBubble } from './MessageBubble';
import { TraceDrawer } from '../EngineeringTrace/TraceDrawer';

interface TurnItemProps {
  message: ChatMessage;
}

export function TurnItem({ message }: TurnItemProps) {
  if (message.role === 'user') {
    return (
      <div className="flex w-full justify-end">
        <MessageBubble message={message} />
      </div>
    );
  }

  const showLiveStatus = Boolean(message.isStreaming && message.status && !message.content);
  const showProse = Boolean(message.content || message.isStreaming);

  return (
    <article className="w-full space-y-3">
      {/* 1) Live Status Pill (auto-hides once text content arrives) */}
      {showLiveStatus && (
        <div className="inline-flex items-center space-x-2 rounded-full border border-[#38BDF8]/30 bg-[#121824] px-3.5 py-1.5 text-xs font-mono text-[#38BDF8] shadow-sm">
          <Loader2 className="h-3.5 w-3.5 animate-spin shrink-0" />
          <span>{message.status}</span>
        </div>
      )}

      {/* 2) Visual Artifact on Top (Plotly chart, KpiCard, DataTableCard, WebIntelligenceCard) */}
      {message.chart && (
        <ChartStage chart={message.chart} minimap={message.minimap || null} />
      )}

      {/* 3) Race Engineer Text Below */}
      {showProse && <MessageBubble message={message} />}

      {/* 4) Collapsible Engineering Trace Bar */}
      {message.trace && <TraceDrawer trace={message.trace} />}
    </article>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import { Loader2, Mic, Send, Zap } from 'lucide-react';
import { PresetPrompts } from './PresetPrompts';

interface ComposerBarProps {
  onSend: (text: string) => void;
  disabled?: boolean;
}

export function ComposerBar({ onSend, disabled }: ComposerBarProps) {
  const [input, setInput] = useState('');
  const [showPrompts, setShowPrompts] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Auto-grow textarea height smoothly up to 140px
  useEffect(() => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = 'auto';
    el.style.height = `${Math.min(el.scrollHeight, 140)}px`;
  }, [input]);

  // Close Quick-Prompts popover on outside click or Escape
  useEffect(() => {
    if (!showPrompts) return;
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setShowPrompts(false);
      }
    };
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setShowPrompts(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [showPrompts]);

  const submitQuery = () => {
    const trimmed = input.trim();
    if (!trimmed || disabled) return;
    onSend(trimmed);
    setInput('');
    setShowPrompts(false);
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    submitQuery();
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      submitQuery();
    }
  };

  return (
    <div
      ref={containerRef}
      className="pointer-events-none fixed inset-x-0 bottom-0 z-30 bg-gradient-to-t from-[#0B0F17] via-[#0B0F17]/95 to-transparent px-4 pb-4 pt-6"
    >
      <div className="pointer-events-auto relative mx-auto w-full max-w-3xl">
        {/* Compact Quick-Prompts Popover */}
        {showPrompts && (
          <div className="absolute bottom-full left-0 right-0 mb-2.5 z-40">
            <PresetPrompts
              onSelect={(prompt) => {
                onSend(prompt);
                setShowPrompts(false);
              }}
              onClose={() => setShowPrompts(false)}
              disabled={disabled}
            />
          </div>
        )}

        {/* Floating Dark Pill Composer */}
        <form
          onSubmit={handleSubmit}
          className="flex items-end gap-2 rounded-2xl border border-[#1E293B] bg-[#121824]/95 px-3 py-2 shadow-2xl backdrop-blur-md focus-within:border-[#38BDF8]/60 transition-colors"
        >
          {/* Compact Quick-Prompts Toggle Button */}
          <button
            type="button"
            onClick={() => setShowPrompts((prev) => !prev)}
            disabled={disabled}
            title="Quick engineering prompts"
            aria-expanded={showPrompts}
            className={`mb-0.5 inline-flex items-center space-x-1.5 rounded-xl border px-2.5 py-2 text-xs font-mono transition-colors shrink-0 disabled:opacity-50 ${
              showPrompts
                ? 'border-[#E10600]/60 bg-[#E10600]/15 text-white'
                : 'border-[#1E293B] bg-[#0B0F17] text-[#CBD5E1] hover:border-[#38BDF8]/50 hover:text-white'
            }`}
          >
            <Zap className="h-3.5 w-3.5 text-[#E10600]" />
            <span className="hidden sm:inline">Prompts</span>
          </button>

          {/* Auto-Growing Textarea */}
          <textarea
            ref={textareaRef}
            rows={1}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            disabled={disabled}
            placeholder="Ask PitWall AI about race results, corner telemetry, or strategy..."
            className="max-h-[140px] flex-1 resize-none bg-transparent py-2 text-sm text-white placeholder-[#64748B] focus:outline-none disabled:opacity-50"
          />

          {/* Reserved Voice Pit-Wall Radio Slot */}
          <button
            type="button"
            disabled
            aria-label="Voice Pit-Wall Radio (coming soon)"
            title="Pit-Wall Voice Radio (coming soon)"
            className="mb-0.5 inline-flex items-center justify-center rounded-xl border border-[#1E293B] bg-[#0B0F17]/70 p-2 text-[#64748B] opacity-70 cursor-not-allowed shrink-0"
          >
            <Mic className="h-4 w-4" />
          </button>

          {/* Send Button */}
          <button
            type="submit"
            disabled={!input.trim() || disabled}
            aria-label="Send message"
            className="mb-0.5 inline-flex items-center justify-center rounded-xl bg-[#E10600] p-2.5 text-white shadow-sm transition-colors hover:bg-[#B80500] disabled:opacity-40 shrink-0"
          >
            {disabled ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Send className="h-4 w-4" />
            )}
          </button>
        </form>
      </div>
    </div>
  );
}

