def get_cors_origins(self) -> List[str]:
    """Parse comma-separated or JSON-array CORS_ORIGINS / CORS_ORIGIN into normalized origins (no trailing '/')."""
    def _parse_raw(raw_val: Optional[str]) -> List[str]:
        raw = (raw_val or "").strip()
        if not raw:
            return []
        if raw.startswith("["):
            try:
                parsed = json.loads(raw)
                if isinstance(parsed, list):
                    items = [str(o).strip() for o in parsed if str(o).strip()]
                    return ["*" if o == "*" else o.rstrip("/") for o in items]
            except Exception:
                pass
        items = [origin.strip() for origin in raw.split(",") if origin.strip()]
        return ["*" if o == "*" else o.rstrip("/") for o in items]

    origins = _parse_raw(os.environ.get("CORS_ORIGINS") or self.CORS_ORIGINS)
    singular_origins = _parse_raw(os.environ.get("CORS_ORIGIN") or self.CORS_ORIGIN)

    merged: List[str] = []
    for origin in origins + singular_origins:
        if origin and origin not in merged:
            merged.append(origin)

    return merged or ["http://localhost:5173", "http://127.0.0.1:5173"]

